const TZ = 'Africa/Lagos';
const s = (v) => String(v === null || v === undefined ? '' : v).trim();
const todayStr = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(new Date());
const nowIso = () => new Date(Date.now() + 3600000).toISOString().replace(/\.\d{3}Z$/, '+01:00');
const uid = (p) => p + '-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 7).toUpperCase();
const isEmail = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s(e));
const isDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d) && !isNaN(Date.parse(d + 'T00:00:00Z'));
const daysBetween = (a, b) => Math.floor((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
const mkLog = (o) => Object.assign({ event_id: uid('EVT'), customer_id: '', email: '', event_type: '', campaign_id: '', email_sequence: '', message_id: '', booking_id: '', timestamp: nowIso(), status: '', error: '', metadata: '' }, o);
const mkErr = (o) => Object.assign({ error_id: uid('ERR'), workflow: '', customer_id: '', node: '', error_type: 'UNKNOWN', message: '', timestamp: nowIso(), retry_count: 0, resolved: 'FALSE', execution_id: String($execution.id) }, o);

function sendBlocked(log, cust, camp, seq) {
  let started = false, fails = 0;
  for (const l of log) {
    if (s(l.customer_id) !== cust || s(l.campaign_id) !== camp || s(l.email_sequence) !== seq) continue;
    if (l.event_type === 'EMAIL_SEND_STARTED') started = true;
    else if (l.event_type === 'EMAIL_FAILED') { started = false; fails++; }
  }
  return { blocked: started, fails };
}

const IN = $('Start').first().json;
const S = $('Get Settings').first().json.settings;
const custId = s(IN.customer_id);
const seq = s(IN.email_sequence) || 'INITIAL';
const customers = $('Read Customers').all().map(i => i.json);
const log = $input.all().map(i => i.json).filter(l => l.event_id);
const matches = customers.filter(c => s(c.customer_id) === custId);
const camp = s(S.campaign_id);
const fail = (reason) => [{ json: { ok: false, reason, custId, seq, logRow: mkLog({
  customer_id: custId, email: s(matches[0] && matches[0].email), event_type: 'SKIPPED', campaign_id: camp,
  email_sequence: seq, status: 'SKIPPED', metadata: reason }) } }];

if (!custId) return fail('MISSING_CUSTOMER_ID');
if (S.campaign_enabled !== 'ON') return fail('CAMPAIGN_OFF');
if (!isEmail(S.sender_email)) return fail('NO_SENDER_EMAIL');
if (!/^https:\/\//i.test(s(S.booking_link))) return fail('BOOKING_LINK_INVALID');
if (matches.length !== 1) return fail(matches.length === 0 ? 'CUSTOMER_NOT_FOUND' : 'DUPLICATE_CUSTOMER_ID');
const c = matches[0];
if (!isEmail(c.email)) return fail('INVALID_EMAIL');
if (s(c.consent_status) !== 'OPTED_IN') return fail('NOT_OPTED_IN');
if (s(c.booking_status) === 'BOOKED') return fail('ALREADY_BOOKED');
const cs = s(c.campaign_status) || 'NOT_STARTED';
if (cs === 'STOPPED' || cs === 'COMPLETED') return fail('CAMPAIGN_' + cs);
if (!s(c.unsubscribe_token)) return fail('NO_UNSUBSCRIBE_TOKEN');
const followCount = Number(c.follow_up_count) || 0;
const m = seq.match(/^FOLLOWUP-(\d+)$/);
if (seq === 'INITIAL') {
  if (!['NOT_STARTED', 'ELIGIBLE'].includes(cs)) return fail('WRONG_STATE_FOR_INITIAL');
} else if (m) {
  const n = Number(m[1]);
  if (!['CONTACTED', 'FOLLOW_UP_PENDING'].includes(cs)) return fail('WRONG_STATE_FOR_FOLLOWUP');
  if (n > S.max_followups) return fail('MAX_FOLLOWUPS_REACHED');
  if (followCount !== n - 1) return fail('SEQUENCE_MISMATCH');
  const lcDate = s(c.last_contacted_at).slice(0, 10);
  if (!isDate(lcDate)) return fail('NO_LAST_CONTACTED_AT');
  if (daysBetween(lcDate, todayStr()) < S.days_between_followups) return fail('TOO_SOON');
} else {
  return fail('BAD_SEQUENCE');
}
const b = sendBlocked(log, custId, camp, seq);
if (b.blocked) return fail('DUPLICATE_SEND_KEY');
if (b.fails >= 3) return fail('RETRY_LIMIT');

const isFollow = seq !== 'INITIAL';
const service = s(c.last_service) || s(S.default_service);
const facts = [
  'Customer first name: ' + (s(c.first_name) || '(unknown - greet with "Hi there")'),
  'Previous service: ' + (service || '(unknown - do not mention a specific service)'),
  'Date of last service: ' + s(c.last_service_date),
  'Business name: ' + s(S.business_name),
  'Tone: ' + (s(S.email_tone) || 'friendly and professional'),
  'Current offer: ' + (s(S.current_offer) || '(none - do not mention any offer)'),
  'Email type: ' + (isFollow ? 'Follow-up number ' + m[1] : 'First reactivation email')
].join('\n');
let system = 'You are writing a short customer reactivation email for a service business.\n\nUse ONLY the information provided.\n\nDo not invent:\n- prices\n- promotions\n- services\n- guarantees\n- dates\n- URLs\n- customer history\n\nKeep the email natural and concise (under 120 words).\nDo not mention automation or AI.\nPut the exact text {{BOOKING_LINK}} on its own line once. Do not write any other links.\nSign off with the business name.\n\nReturn JSON only:\n{"subject": "...", "body": "..."}';
if (isFollow) system += '\n\nThis is follow-up number ' + m[1] + '. Write a shorter, gentler nudge. Do not pretend the customer replied or refer to earlier replies.';
const aiRequest = { model: S.openai_model || 'gpt-4o-mini', n: 2, temperature: 0.7, max_tokens: 400,
  response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: system }, { role: 'user', content: facts }] };
return [{ json: { ok: true, custId, seq, settings: S, customer: c, aiRequest } }];

const TZ = 'Africa/Lagos';
const s = (v) => String(v === null || v === undefined ? '' : v).trim();
const todayStr = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(new Date());
const nowIso = () => new Date(Date.now() + 3600000).toISOString().replace(/\.\d{3}Z$/, '+01:00');
const uid = (p) => p + '-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 7).toUpperCase();
const isEmail = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s(e));
const isDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d) && !isNaN(Date.parse(d + 'T00:00:00Z'));
const daysBetween = (a, b) => Math.floor((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
const mkLog = (o) => Object.assign({ event_id: uid('EVT'), customer_id: '', email: '', event_type: '', campaign_id: '', email_sequence: '', message_id: '', booking_id: '', timestamp: nowIso(), status: '', error: '', metadata: '' }, o);
const mkErr = (o) => Object.assign({ error_id: uid('ERR'), workflow: '', customer_id: '', node: '', error_type: 'UNKNOWN', message: '', timestamp: nowIso(), retry_count: 0, resolved: 'FALSE', execution_id: String($execution.id) }, o);

const P = $('Pre-send Checks').first().json;
const S = P.settings, c = P.customer, seq = P.seq, custId = P.custId;
const camp = s(S.campaign_id), email = s(c.email);
const resp = $input.first().json || {};
const cands = [];
if (Array.isArray(resp.choices)) for (const ch of resp.choices) cands.push((ch && ch.message && ch.message.content) || '');
let apiError = '';
if (resp.error) apiError = (typeof resp.error === 'string' ? resp.error : (resp.error.message || JSON.stringify(resp.error))).slice(0, 300);
const inputsText = [S.current_offer, S.business_name, S.default_service, c.last_service, c.first_name, S.email_tone].map(x => s(x).toLowerCase()).join(' ');
const otherNames = $('Read Customers').all().map(i => s(i.json.first_name))
  .filter(n => n.length >= 3 && n.toLowerCase() !== s(c.first_name).toLowerCase() && !inputsText.includes(n.toLowerCase()));

function validate(raw) {
  let o;
  try { o = JSON.parse(String(raw).replace(/^```(?:json)?\s*|\s*```$/g, '').trim()); } catch (e) { return { ok: false, reason: 'BAD_JSON' }; }
  const subject = typeof o.subject === 'string' ? o.subject.trim() : '';
  const body = typeof o.body === 'string' ? o.body.trim() : '';
  if (!subject || subject.length > 120) return { ok: false, reason: 'BAD_SUBJECT' };
  if (body.length < 20 || body.length > 1500) return { ok: false, reason: 'BAD_BODY_LENGTH' };
  if ((body.match(/\{\{BOOKING_LINK\}\}/g) || []).length !== 1) return { ok: false, reason: 'BOOKING_PLACEHOLDER' };
  if (subject.includes('{{')) return { ok: false, reason: 'PLACEHOLDER_IN_SUBJECT' };
  const text = subject + '\n' + body.replace('{{BOOKING_LINK}}', '');
  const low = text.toLowerCase();
  if (/https?:\/\/|www\.|\b[a-z0-9-]+\.(com|net|org|ng|io|co|info|biz)\b/i.test(text)) return { ok: false, reason: 'URL_FOUND' };
  if (/[$\u20AC\u00A3\u20A6]|%/.test(text)) return { ok: false, reason: 'CURRENCY_OR_PERCENT' };
  for (const w of ['discount', 'free', 'guarantee']) if (low.includes(w) && !inputsText.includes(w)) return { ok: false, reason: 'BANNED_WORD_' + w.toUpperCase() };
  if (/\boff\b/i.test(text) && !/\boff\b/.test(inputsText)) return { ok: false, reason: 'BANNED_WORD_OFF' };
  if (/\bAI\b/.test(text) || /automat(ed|ion|ic)|artificial intelligence/i.test(text)) return { ok: false, reason: 'MENTIONS_AI' };
  for (const n of otherNames) if (new RegExp('\\b' + n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i').test(text)) return { ok: false, reason: 'OTHER_CUSTOMER_NAME' };
  return { ok: true, subject, body };
}

let good = null;
const reasons = [];
for (const raw of cands) { const v = validate(raw); if (v.ok) { good = v; break; } reasons.push(v.reason); }
if (!good) {
  const reason = apiError ? 'OPENAI_API_ERROR' : (reasons[0] || 'NO_CANDIDATES');
  return [{ json: { valid: false, reason, custId, seq,
    logRow: mkLog({ customer_id: custId, email, event_type: 'AI_INVALID_OUTPUT', campaign_id: camp, email_sequence: seq, status: 'FAILED', error: apiError || reason, metadata: reasons.join(',') }),
    errorRow: mkErr({ workflow: 'WF2 - Send Campaign Email', customer_id: custId, node: 'OpenAI Generate Email', error_type: apiError ? 'API_ERROR' : 'AI_INVALID_OUTPUT', message: apiError || reason }) } }];
}
const base = s(S.booking_link);
const name = [s(c.first_name), s(c.last_name)].filter(Boolean).join(' ');
const link = base + (base.includes('?') ? '&' : '?') + 'name=' + encodeURIComponent(name) + '&email=' + encodeURIComponent(email) + '&customer_id=' + encodeURIComponent(custId);
const unsub = s(S.public_base_url).replace(/\/+$/, '') + '/webhook/unsubscribe?t=' + encodeURIComponent(s(c.unsubscribe_token));
const text = good.body.replace('{{BOOKING_LINK}}', link) + '\n\n--\n' + s(S.business_name) + '\nDon\'t want these emails? Unsubscribe here: ' + unsub;
return [{ json: { valid: true, custId, seq, camp, email, maxFollowups: S.max_followups,
  fromEmail: s(S.sender_name) + ' <' + s(S.sender_email) + '>', to: email, replyTo: s(S.business_email) || s(S.sender_email),
  subject: good.subject, text,
  startedRow: mkLog({ customer_id: custId, email, event_type: 'EMAIL_SEND_STARTED', campaign_id: camp, email_sequence: seq, status: 'STARTED' }) } }];

const TZ = 'Africa/Lagos';
const s = (v) => String(v === null || v === undefined ? '' : v).trim();
const todayStr = () => new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(new Date());
const nowIso = () => new Date(Date.now() + 3600000).toISOString().replace(/\.\d{3}Z$/, '+01:00');
const uid = (p) => p + '-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2, 7).toUpperCase();
const isEmail = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s(e));
const isDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d) && !isNaN(Date.parse(d + 'T00:00:00Z'));
const daysBetween = (a, b) => Math.floor((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
const mkLog = (o) => Object.assign({ event_id: uid('EVT'), customer_id: '', email: '', event_type: '', campaign_id: '', email_sequence: '', message_id: '', booking_id: '', timestamp: nowIso(), status: '', error: '', metadata: '' }, o);
const mkErr = (o) => Object.assign({ error_id: uid('ERR'), workflow: '', customer_id: '', node: '', error_type: 'UNKNOWN', message: '', timestamp: nowIso(), retry_count: 0, resolved: 'FALSE', execution_id: String($execution.id) }, o);

const V = $('Validate AI & Build Email').first().json;
const r = $input.first().json || {};
const errText = r.error ? (typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error))) : '';
const sent = !errText;
const now = nowIso();
const n = V.seq === 'INITIAL' ? 0 : Number(V.seq.split('-')[1]);
const status = n >= V.maxFollowups ? 'COMPLETED' : (n === 0 ? 'CONTACTED' : 'FOLLOW_UP_PENDING');
const base = { customer_id: V.custId, email: V.email, campaign_id: V.camp, email_sequence: V.seq };
let logRow, customerUpdate = null, errorRow = null;
if (sent) {
  logRow = mkLog(Object.assign({}, base, { event_type: 'EMAIL_SENT', message_id: s(r.messageId), status: 'SUCCESS' }));
  customerUpdate = { customer_id: V.custId, campaign_status: status, follow_up_count: n, last_contacted_at: now, updated_at: now };
} else {
  logRow = mkLog(Object.assign({}, base, { event_type: 'EMAIL_FAILED', status: 'FAILED', error: errText.slice(0, 300) }));
  errorRow = mkErr({ workflow: 'WF2 - Send Campaign Email', customer_id: V.custId, node: 'Send Email (Gmail SMTP)', error_type: 'API_ERROR', message: errText.slice(0, 300), retry_count: 3 });
}
return [{ json: { sent, logRow, customerUpdate, errorRow, result: { result: sent ? 'SENT' : 'FAILED', customer_id: V.custId, email_sequence: V.seq, error: errText } } }];
